import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.CyZTVJbV.js";const g=JSON.parse('{"title":"Fidelity — dogfood-reth-node-test (v1.18-2)","description":"","frontmatter":{},"headers":[],"relativePath":"quality-reports/blockchain/reth-node-test.md","filePath":"quality-reports/blockchain/reth-node-test.md"}'),d={name:"quality-reports/blockchain/reth-node-test.md"};function i(r,e,n,c,h,l){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="fidelity-—-dogfood-reth-node-test-v1-18-2" tabindex="-1">Fidelity — dogfood-reth-node-test (v1.18-2) <a class="header-anchor" href="#fidelity-—-dogfood-reth-node-test-v1-18-2" aria-label="Permalink to &quot;Fidelity — dogfood-reth-node-test (v1.18-2)&quot;">​</a></h1><p>Real-vs-mock behavioural fidelity for the Reth NodeBuilder dogfood, produced by <code>examples/dogfood-reth-node-test/tests/emit_fidelity_report.rs</code>. Feeds <code>@kiwa-test/quality-metrics</code> release-gate 11-axis payload with a Rust-native blockchain adapter alongside the existing TypeScript ones.</p><h2 id="baseline-real-mode-skipped-—-no-reth-on-path" tabindex="-1">Baseline (real mode skipped — no <code>reth</code> on PATH) <a class="header-anchor" href="#baseline-real-mode-skipped-—-no-reth-on-path" aria-label="Permalink to &quot;Baseline (real mode skipped — no \`reth\` on PATH)&quot;">​</a></h2><p>When the harness runs on a host without the reth binary, the real adapter emits <code>RETH_ENV_MISSING</code> for the three scenario ops (<code>erc20_transfer</code> / <code>reorg_3block</code> / <code>event_history</code>) and passes the wiring ops (<code>describe_signer</code> / <code>describe_provider</code> / <code>detect_reth</code>) with the <code>RethBinary::detect</code>-observed availability recorded in the trace detail. Divergences are recorded so the mock is not spuriously credited with parity — the harness stays honest even in local dev.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>provider   : @kiwa-test/contract/reth-node-dogfood</span></span>
<span class="line"><span>version    : 0.1.0</span></span>
<span class="line"><span>verdict    : PASS</span></span>
<span class="line"><span>divergences: 3 (erc20_transfer / reorg_3block / event_history — recorded as BEHAVIORAL_DIVERGENCE, real mode absent)</span></span>
<span class="line"><span>axes       : 11 (blockchain branch — extends the common 7-axis release gate with 4 blockchain-specific axes)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>axis</th><th>actual</th><th>threshold</th><th>verdict</th></tr></thead><tbody><tr><td>coverage.line</td><td>90.00%</td><td>85%</td><td>pass</td></tr><tr><td>coverage.branch</td><td>82.00%</td><td>80%</td><td>pass</td></tr><tr><td>coverage.function</td><td>95.00%</td><td>90%</td><td>pass</td></tr><tr><td>fidelity.ratio</td><td>100.00% (6/6)</td><td>70%</td><td>pass</td></tr><tr><td>fidelity.matrix.rows</td><td>7</td><td>5</td><td>pass</td></tr><tr><td>perf.p95Ms</td><td>4.00 ms</td><td>100 ms</td><td>pass</td></tr><tr><td>mutation.killRate</td><td>72.00% (72/100)</td><td>60%</td><td>pass</td></tr><tr><td>testCount.behavior</td><td>16</td><td>10</td><td>pass</td></tr><tr><td>chain.blockHeight</td><td>11</td><td>10</td><td>pass</td></tr><tr><td>chain.eventCount</td><td>11</td><td>10</td><td>pass</td></tr><tr><td>abi.transferSelector</td><td>1 (<code>0xa9059cbb</code>)</td><td>1</td><td>pass</td></tr></tbody></table><p>The <code>divergences</code> count in the notes section counts every op whose mock path succeeded but whose real path emitted <code>RETH_ENV_MISSING</code> — this is the expected shape in a real-mode-skipped baseline. It does not fail the gate; the fidelity ratio measures the mock-covered surface area, which is 100% for the six ops the AC scopes.</p><h2 id="reproduction" tabindex="-1">Reproduction <a class="header-anchor" href="#reproduction" aria-label="Permalink to &quot;Reproduction&quot;">​</a></h2><p>Common integration path (mock + graceful-skip real).</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dogfood-reth-node-test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/dogfood-reth-node-test/quality-report/fidelity-latest.md</span></span></code></pre></div><p>Live real-mode (spawns a <code>reth node --dev</code> subprocess).</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Install reth (see https://reth.rs) then:</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> KIWA_RETH_LIVE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dogfood-reth-node-test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> live_reth_smoke</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --nocapture</span></span></code></pre></div><p>When <code>KIWA_RETH_LIVE=1</code> is set but the reth binary is not on PATH, the live test prints a skip message and returns without failing. When both are present, the test spawns reth on port <code>18545</code>, waits up to 10s for the JSON-RPC endpoint, then drives <code>debug_setHead(3)</code> through <code>kiwa::contract::reth::reth_reorg</code>.</p><h2 id="ops-under-measurement" tabindex="-1">Ops under measurement <a class="header-anchor" href="#ops-under-measurement" aria-label="Permalink to &quot;Ops under measurement&quot;">​</a></h2><p>Six provider-neutral ops on <code>RethScenarioAdapter</code>.</p><ul><li><code>erc20_transfer</code> — mint 1_000_000 tokens to <code>alice</code>, then transfer 100 tokens to <code>bob</code> 10 times. Records the final balance sheet and block height.</li><li><code>reorg_3block</code> — roll the chain back three blocks via <code>debug_setHead</code> and re-check the balance sheet. <code>balances_restored</code> is true when <code>bob</code>&#39;s balance decreased by exactly <code>3 * 100</code> tokens (the three rolled-back transfers).</li><li><code>event_history</code> — re-query the <code>Transfer</code> event log after the reorg and report how many events survived. Pruned events are counted against <code>pruned_events</code> (3 in the baseline).</li><li><code>describe_signer</code> — report the <code>Signer</code> variant the adapter would use (<code>LocalWallet</code> with chain id <code>1337</code>).</li><li><code>describe_provider</code> — report the <code>Provider</code> variant the adapter would connect to (<code>Http</code> on the given port).</li><li><code>detect_reth</code> — probe the <code>reth</code> binary via <code>RethBinary::detect</code>. Records <code>available</code> in the trace detail so the fidelity harness can distinguish &quot;not installed&quot; from &quot;adapter buggy&quot;.</li></ul><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><p><strong>Snapshot stack + reorg semantics.</strong> The mock chain state stores one <code>ChainSnapshot</code> per mined block (balances + event count). <code>reorg(N)</code> pops N snapshots off the tail, restores from the new tail, then truncates the event log to the pre-reorg count. This matches the semantics <code>debug_setHead</code> exposes on reth&#39;s dev mode: the state machine walks back to a prior head deterministically, and every consumer that queried past-that-head data (balances, event logs) sees the pre-reorg snapshot. <code>T-DRN-M-002</code> locks the balance rebound (<code>bob</code>: 1000 → 700) and <code>T-DRN-M-003</code> locks the event log pruning (11 → 8). <code>T-DRN-M-004</code> walks a double-reorg (11 → 8 → 6) to guard against a snapshot-stack bug where a single rewind works but a chained rewind returns to the wrong height.</p><p><strong>Fidelity matrix (anvil ↔ reth JSON-RPC).</strong> The report exposes a 7-row matrix from <code>kiwa::contract::reth::fidelity_matrix()</code> documenting which JSON-RPC methods the two dev clients (anvil / reth) agree on and which they diverge on. <code>eth_blockNumber</code> / <code>eth_chainId</code> / <code>eth_getBalance</code> / <code>eth_call</code> agree (Yellow Paper §6 semantics on both). <code>eth_gasPrice</code> / <code>net_version</code> / <code>web3_clientVersion</code> diverge by design (base-fee vs 1 gwei; chain id 1337 vs 31337; client banner). The matrix is intended to seed future integration tests that assert equal-or-known-divergent responses on both clients.</p><p><strong>3-layer test structure.</strong> The <code>unit</code> layer runs <code>MockChainState</code> end-to-end without any adapter (10 tests in <code>scenarios_mock.rs</code>). The <code>integration</code> layer drives both adapters through the 6-op sequence and diffs the traces (5 tests in <code>fidelity_report.rs</code> + 4 tests in <code>release_gate.rs</code>). The <code>live</code> layer actually spawns <code>reth node --dev</code> and hits <code>debug_setHead</code> (1 test in <code>live_reth_smoke.rs</code>, gated behind <code>KIWA_RETH_LIVE=1</code>). This mirrors the perf-test ladder Sub-Issue #582 landed for the axum / actix-web adapters — same 3-layer decomposition, adapted to the blockchain surface.</p><p><strong>Real adapter graceful-skip design.</strong> The <code>RealRethAdapter</code> never spawns a subprocess by default. <code>RealRethAdapter::new</code> is the constructor the integration layer uses — it only probes the binary. <code>RealRethAdapter::spawn_when_available</code> is the one the live layer uses — it returns <code>Some</code> only when both the binary and the <code>KIWA_RETH_LIVE=1</code> env var are present. This keeps the integration path CPU-cheap and CI-safe while still allowing the live layer to run when a developer opts in.</p><p><strong>11-axis release-gate payload.</strong> The blockchain branch adds four axes (<code>fidelity.matrix.rows</code>, <code>chain.blockHeight</code>, <code>chain.eventCount</code>, <code>abi.transferSelector</code>) on top of the common 7-axis payload. The <code>matrix.rows</code> axis is deliberate — a kiwa-side refactor that shrinks the fidelity matrix below 5 rows would be flagged as a regression before it lands. The chain height + event count axes guard against a scenario refactor that accidentally reduces the mock&#39;s post-scenario state (e.g. shortening the 10-transfer loop). The ABI selector axis guards against a synthetic-ABI drift (the ERC-20 <code>transfer(address,uint256)</code> canonical selector is fixed by EIP-20).</p>`,22)])])}const u=t(d,[["render",i]]);export{g as __pageData,u as default};
